package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/signal"
	"runtime"
	"syscall"
)

var (
	version   = "dev"
	commit    = "unknown"
	buildTime = "unknown"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		log.Printf("ERROR: %v", err)
		os.Exit(1)
	}
}

func run(arguments []string) error {
	flags := flag.NewFlagSet("automation-gateway-led", flag.ContinueOnError)
	flags.SetOutput(os.Stderr)
	configPath := flags.String("config", "/etc/automation-gateway-led/config.yaml", "configuration file")
	check := flags.Bool("check", false, "validate configuration and credentials without accessing hardware")
	showVersion := flags.Bool("version", false, "print version and exit")
	if err := flags.Parse(arguments); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return fmt.Errorf("unexpected positional arguments: %v", flags.Args())
	}
	if *showVersion {
		fmt.Printf("automation-gateway-led %s (commit %s, built %s, %s/%s)\n", version, commit, buildTime, runtime.GOOS, runtime.GOARCH)
		return nil
	}

	logger := log.New(os.Stderr, "automation-gateway-led: ", log.LstdFlags)
	logger.Printf("starting version=%s commit=%s built=%s", version, commit, buildTime)
	config, token, err := loadConfig(*configPath)
	if err != nil {
		return err
	}
	client, err := newHTTPClient(config)
	if err != nil {
		return err
	}
	if *check {
		fmt.Println("configuration is valid")
		return nil
	}

	image := newGoPiControlImage()
	device, err := newLEDDevice(image, config.LED)
	if err != nil {
		_ = image.Close()
		return err
	}
	defer device.Close()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	updates := make(chan statusInput, 16)
	go followGateway(ctx, config, token, client, updates, logger)
	return driveIndicator(ctx, device, config.ActivityHold, updates)
}
